306	/**
307	 * Normalize meal-break specs into `{startMin, endMin}` minute-of-day ranges,
308	 * dropping ones that are disabled (`enabled === false`), malformed, or
309	 * zero/negative length. Accepts `{startMin, endMin}` numbers or `{start, end}`
310	 * "HH:MM" strings.
311	 * @param {Array<{startMin?:number,endMin?:number,start?:string,end?:string,enabled?:boolean}>} breaks
312	 * @returns {Array<{startMin:number, endMin:number}>}
313	 */
314	export function normalizeMealBreaks(breaks) {
315	  if (!Array.isArray(breaks)) return [];
316	  const out = [];
317	  for (const b of breaks) {
318	    if (!b || b.enabled === false) continue;
319	    const startMin = b.startMin ?? (b.start != null ? timeToMinutesOfDay(b.start) : null);
320	    const endMin = b.endMin ?? (b.end != null ? timeToMinutesOfDay(b.end) : null);
321	    if (startMin == null || endMin == null || endMin <= startMin) continue;
322	    out.push({ startMin, endMin });
323	  }
324	  return out;
325	}
