329	 * day end, and overlaps none of the meal breaks — the day-hours filter the
330	 * scheduler applies before allocating.
331	 * @param {Slot} slot
332	 * @param {{dayStartMin?:number, dayEndMin?:number, mealBreaks?:Array<{startMin:number,endMin:number}>}} [win]
333	 * @returns {boolean}
334	 */
335	export function withinDayWindow(slot, win = {}) {
336	  const dayStartMin = win.dayStartMin ?? 0;
337	  const dayEndMin = win.dayEndMin ?? 1440;
338	  if (slot.startMinuteOfDay < dayStartMin) return false;
339	  if (slot.endMinuteOfDay > dayEndMin) return false;
340	  for (const b of win.mealBreaks || []) {
341	    // Overlap (half-open): a show touching a break edge-to-edge is fine.
342	    if (slot.startMinuteOfDay < b.endMin && slot.endMinuteOfDay > b.startMin) return false;
343	  }
344	  return true;
345	}
