351	 * unknown) and the estimated door-to-door travel time by the chosen mode, so
352	 * the gap grows with distance and shrinks on a bike/car. Extends
353	 * scheduling.py's `required_gap_minutes` with the travel estimate.
354	 * @param {Slot} a
355	 * @param {Slot} b
356	 * @param {{minGapSameVenue?: number, minGapDifferentVenue?: number, travelMode?: string}} [options]
357	 * @returns {number}
358	 */
359	export function requiredGapMinutes(a, b, options = {}) {
360	  const minGapSameVenue = options.minGapSameVenue ?? DEFAULT_MIN_GAP_SAME_VENUE;
361	  const minGapDifferentVenue = options.minGapDifferentVenue ?? DEFAULT_MIN_GAP_DIFFERENT_VENUE;
362	  if (a.venueCode && b.venueCode && a.venueCode === b.venueCode) {
363	    return minGapSameVenue;
